FAMILIES={
'input-output':('input → mechanism → outcome','Explain how a source becomes an output through a named mechanism.', ['{{input_source}} feeds {{mechanism}}, which produces {{outcome}}.','For {{bounded_task}}, {{system}} can use {{input_source}} to produce {{qualified_result}}.'],['input_source','mechanism','outcome','qualification'], 'Use when the causal route is the lesson and each arrow has a defensible meaning.','Use real UI for exact interaction steps; do not use an outcome card as evidence that execution succeeded.','Introduce the role named first by the narration, then add the remaining input/mechanism/output roles at their spoken cues. Hold the complete relationship. Reading direction does not determine reveal order.'),
'converging-sources':('many inputs → shared hub','Show several distinct sources contributing context or capabilities to one named consumer.', ['{{consumer}} draws on {{source_a}}, {{source_b}} and {{source_c}} to {{job}}.','These inputs differ, but they contribute to the same {{shared_layer}}.'],['consumer','sources','shared_layer','job'],'Use when the distinction among source classes matters and they share a real destination.','Use a list for unrelated items; label search/query/tool access rather than implying data ingestion.','Add sources individually, retain earlier nodes, draw each path, then activate the hub.'),
'product-definition':('name → role → concrete capability','Introduce a product or concept with one precise role before adding system detail.', ['{{concept}} is {{category}} that {{capability}}.','You give {{system}} {{input}}; it helps you {{specific_job}}.'],['concept','category','capability','input','specific_job'],'Use when the viewer needs a definition before a mechanism or example.','Do not use a logo reveal to explain an internal architecture.','Introduce the name and role; settle before expanding the surrounding context.'),
'worked-example':('question → reasoning/result → action','Turn an abstract capability into a concrete question and observable answer or suggested action.', ['Suppose you ask {{concrete_question}}. {{system}} uses {{evidence}} to {{result}}.','From that answer, you can {{next_action}}, subject to {{constraint}}.'],['concrete_question','evidence','result','next_action','constraint'],'Use after a capability needs a tangible demonstration.','Use genuine product footage for actual execution; label invented chat examples as illustrative.','Establish the prompt, reveal its response, then add the next action; keep the question visible.'),
'governance-boundary':('capability inside a constraint','Explain what controls access or action without losing the underlying workflow.', ['{{system}} can {{capability}}, but only within {{policy_boundary}}.','{{governance_layer}} controls which {{assets_or_actions}} {{actor}} may use.'],['system','capability','policy_boundary','governance_layer','actor','assets_or_actions'],'Use when a boundary constrains an otherwise understandable flow.','A shield alone does not explain a permission model; identify the actor, scope and enforcement point.','Keep the workflow and add an enclosure or labeled control point; reveal permitted and denied routes.'),
'product-family':('shared foundation → different roles','Compare related offerings while distinguishing their jobs.', ['{{family}} shares {{foundation}}, while {{product_a}} serves {{job_a}} and {{product_b}} serves {{job_b}}.','These are different ways to use {{shared_capability}}, depending on {{user_job}}.'],['family','foundation','products','jobs','user_job'],'Use when the products are peers with shared foundations.','Do not turn peer products into an execution pipeline or imply dependency from card depth.','Show a shared stack, then spread peer cards while preserving the front card and each readable plane.'),
'wrong-source':('question → plausible but wrong asset → wrong answer','Expose a source-selection failure using a concrete business example.', ['For {{business_question}}, {{system}} may select {{easy_but_wrong_asset}} instead of {{authoritative_asset}}.','It finds {{candidate}}, but that is not the {{trusted_definition_or_source}} used by {{owner}}.'],['business_question','system','easy_but_wrong_asset','authoritative_asset','owner'],'Use when the failure is asset authority or relevance rather than arithmetic.','Use a definition comparison for metric ambiguity; avoid showing a random table when the problem is a formula.','Establish candidate assets, highlight the wrong selection, connect it to the answer and expose the error.'),
'metric-ambiguity':('same term → missing rule → changed interpretation','Show how a business definition changes the meaning of a metric or question.', ['When we say {{metric}}, we mean {{definition}}, including {{included_population}} and excluding {{excluded_population}}.','Without {{business_rule}}, {{system}} interprets {{term}} differently from {{team}}.'],['metric','definition','included_population','excluded_population','business_rule','team'],'Use when scope, exclusions or semantics cause ambiguity.','Use a source-authority graphic for choosing among tables; do not imply a definition alone repairs stale data.','Keep the question, introduce the missing rule beside the mechanism, and make the interpretation difference visible.'),
'stale-context':('prior context → change → mismatch','Explain why yesterday’s context or assets no longer match today’s question.', ['{{asset_or_rule}} changed, but {{system}} still uses {{old_context}}.','The {{entity}} was {{change}}, so the previous {{reference}} is now unreliable.'],['asset_or_rule','change','old_context','entity','reference'],'Use when time or organizational change breaks relevance.','A stale icon does not prove freshness checks exist; show the changed reference and its consequence.','Reveal the original reference, mark the concrete change, then show the resulting mismatch.'),
'context-repair':('broken route → missing context → repaired route','Show how named business context improves an otherwise ambiguous route.', ['To answer {{question}} correctly, connect {{data}} with {{definition_or_context}}.','The missing piece is {{business_context}}, which tells {{system}} how to interpret {{asset}}.'],['question','data','definition_or_context','business_context','system','asset'],'Use after a concrete failure has established why the missing context matters.','Do not promise that context fixes all data-quality, model or authorization failures.','Retain the failed route, add the specific missing context, reconnect the relevant paths and hold the repaired relationship.'),
'architecture-focus':('system overview → located detail','Locate a component within an architecture before examining it.', ['At a high level, {{system}} contains {{components}}. Let’s focus on {{component}}.','{{component}} sits between {{upstream}} and {{downstream}} and is responsible for {{responsibility}}.'],['system','components','component','upstream','downstream','responsibility'],'Use when placement in the larger system is part of the explanation.','Use a standalone example when the architecture adds no relevant context.','Establish the overview, preserve context, move the inner camera or selectively emphasize the active region.'),
'governed-hierarchy':('governing parent → peers → logical groups','Explain a governed organizational hierarchy with named objects.', ['{{governance_parent}} manages {{object_a}} and {{object_b}}; {{group}} organizes them by {{business_scope}}.','Start with {{definition_object}}, add {{context_object}}, then organize them into {{domain}}.'],['governance_parent','objects','group','business_scope','domain'],'Use for a real parent, containment or grouping relationship.','Use equal peer cards when no parent-child relationship exists; do not invent permission inheritance.','Introduce one object, its governing parent, peer objects, grouping and supported consumers in sequence.'),
'learned-signals':('work evidence → contextual signals','Explain where inferred context comes from using concrete examples of real work.', ['When people {{work_action}}, they leave {{signal}} that helps {{system}} infer {{context}}.','{{example_a}} and {{example_b}} provide clues about {{business_relationship}}.'],['work_action','signal','system','context','examples','business_relationship'],'Use when the lesson is how evidence contributes contextual clues.','Do not represent learned signals as certified definitions or guaranteed truth.','Accumulate labeled source examples, show the new signal, and retain the distinction between evidence and authority.'),
'ranked-context':('candidate context → ranking criteria → relevant context','Explain how a system chooses among contextual candidates.', ['{{system}} prioritizes {{context}} using {{criterion_a}}, {{criterion_b}} and {{criterion_c}}.','Not every {{candidate}} is equally useful; {{ranking_rule}} changes which ones matter for {{question}}.'],['system','context','criteria','candidate','ranking_rule','question'],'Use when relevance or prioritization is the causal lesson.','A generic node graph does not explain ranking; name the criteria and avoid inventing numerical weights.','Establish candidates, focus the ranking mechanism, expose named criteria and return to consumers.'),
'benchmark':('methods × measures → qualified comparison','Compare measured alternatives on explicit dimensions with source qualifications.', ['On {{evaluation_scope}}, {{method_a}} achieved {{measure_a}}, compared with {{method_b}} at {{measure_b}}.','The trade-off is {{dimension_a}} versus {{dimension_b}}, under {{test_conditions}}.'],['evaluation_scope','methods','measures','dimensions','test_conditions'],'Use for comparable measured data with a credible evaluation scope.','Do not transfer source benchmark values to another product or imply universal results from one evaluation.','Fix axes and method order, build bars, introduce the interpretation after values, retain the qualification.'),
'access-paths':('distinct access modes → different jobs','Separate retrieval, live query and tool calls by the work each performs.', ['Use {{access_mode_a}} for {{job_a}}, and {{access_mode_b}} for {{job_b}}.','Finding an existing {{document}} differs from calculating {{answer}} over live {{data}}.'],['access_modes','jobs','document','answer','data'],'Use when superficially similar access paths have different semantics.','A collage of logos cannot distinguish retrieval from execution or ingestion.','Introduce categories, demonstrate one contrast, then connect the supported paths to a shared consumer.'),
'feature-evidence':('stable capability → supporting product evidence','Teach a capability while showing authentic interface evidence of the interaction.', ['To {{user_job}}, use {{feature}}: {{specific_interaction}}.','Here {{system}} lets {{actor}} {{action}}, with {{constraint}}.'],['user_job','feature','specific_interaction','actor','action','constraint'],'Use when the actual visible product interaction supports the claim.','Do not fabricate UI or infer availability beyond the visible source version.','Hold the heading; update one supporting point as the real interface demonstrates it.'),
'permissioned-action':('actor → control point → allowed/denied route','Explain how tool use or write actions are governed.', ['{{actor}} reaches {{tool}} through {{control_point}}, which enforces {{scope}}.','{{action}} is allowed for {{allowed_scope}} and denied for {{denied_scope}}.'],['actor','tool','control_point','scope','action','allowed_scope','denied_scope'],'Use when the permission boundary or action route matters.','Compatibility logos are not proof of authorization or successful execution.','Establish actor and destination, add the gateway, draw the route and reveal access distinctions.'),
'peer-categories':('equal-rank needs or choices','Compare distinct needs at the same conceptual level.', ['We need {{need_a}}, {{need_b}} and {{need_c}} for {{goal}}.','There are three distinct concerns: {{concern_a}}, {{concern_b}} and {{concern_c}}.'],['needs','concerns','goal'],'Use when equal conceptual rank is the lesson.','Use a timeline when order matters and a hierarchy when one item contains another.','Settle one card, make room coherently, then introduce equal peers on a shared baseline.'),
'agent-delegation':('parent → specialists → resources','Distinguish an orchestrating agent from delegated specialists and their resources.', ['{{parent_agent}} delegates {{job_a}} to {{specialist_a}} and {{job_b}} to {{specialist_b}}.','Each {{specialist}} receives {{inputs}} and can use {{resources}} within {{scope}}.'],['parent_agent','specialists','jobs','inputs','resources','scope'],'Use when delegation or ownership is a real relationship in the supported system.','Use an input map for context sources; do not present source connectors as subordinate agents.','Establish the parent or inputs, reveal specialists individually, then show each named branch/resource.'),
'rollout':('ordered milestones → current step → details','Teach an implementation process while preserving accumulated progress.', ['Start with {{team_and_workflow}}, define {{benchmark}}, measure {{baseline}}, then connect {{sources}} and iterate.','At {{current_step}}, do {{task}} so that {{next_step}} has {{required_input}}.'],['team_and_workflow','benchmark','baseline','sources','current_step','task','next_step','required_input'],'Use for a real ordered process with useful current-step context.','Use peer cards for unordered considerations; a rail is not a promise about calendar duration.','Retain earlier milestones, activate the next marker, update details below and pan only when space is exhausted.'),
'fixed-emphasis':('fixed recommendations → one active item','Walk through a complete recommendation set without changing its spatial organization.', ['First {{recommendation_a}}. Next {{recommendation_b}}. Finally {{recommendation_c}}.','For {{goal}}, check {{requirement}} because {{reason}}.'],['recommendations','goal','requirement','reason'],'Use when scanning the whole recommendation set helps orientation.','Do not fade inactive text below legibility or replace the list with unrelated slides.','Keep rows fixed and advance selective emphasis with the narrated topic; hold each active recommendation.'),
'callout':('spoken concept → concise emphasis','Make a named phrase visible without adding an unspoken relationship.', ['The key idea is {{concept}}.','We need both {{concern_a}} and {{concern_b}}.'],['concept','concerns'],'Use for a short framing or recap phrase.','Use a diagram when the mechanism needs explanation; a floating word is insufficient.','Reveal the named phrase or pill at the speech cue, retain it only while it supports the point.'),
'chapter':('chapter transition','Reset attention as the narration changes sections.', ['Now let’s look at {{next_section}}.','We have covered {{previous_topic}}; next is {{next_topic}}.'],['next_section','previous_topic','next_topic'],'Use for a real structural transition.','A chapter title is navigation, not an explanatory mechanism.','Brief clear title hold, then transition to the next teaching surface.'),
'ui-evidence':('actual workflow → visible execution/result','Show the authentic product steps and results rather than inventing them.', ['Here is {{question_or_task}}. We {{interaction}}, then inspect {{result_or_evidence}}.','To verify {{claim}}, look at {{visible_evidence}} in the product.'],['question_or_task','interaction','result_or_evidence','claim','visible_evidence'],'Use when exact interaction or observed execution is central.','Illustrative diagrams cannot verify real execution. Keep reference UI separate from generated conceptual graphics.','Retain real viewport changes and source timing; focus on the evidence the narrator discusses.')
}
